// TH14 synthetic training aliases (see transcribe/th14/bullet-types.md).
// Native 0..23 -> modern 0..23; native 24..42 -> modern 25..43.
const TH14_NOTE_BLUE: int = 992;   // native type 39
const TH14_NOTE_YELLOW: int = 1008; // native type 40

// TH14 v1.00b st04bs::BossCard1 (route A, SHOTTYPE 0/2/4) + BossCard1_at.
// Source entry st04bs::Boss: position (0,128), hurtbox/hitbox 48x48 (target radius 24), lifeSet(2300).
// Source t0 = card frame 120; source slot-0 interrupt at t2400 ends firing (Boss2 timeout branch clears).
const TIME_LIMIT: int = 3024;
const SOURCE_LIMIT: int = 2400;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 40;

// BossCard1_at EX chain per fired ring: etEx VELTIME(0x200000,a=60,r=0,keep angle),
// then appended STEP(0x10,a=2k,b=1,c=0,r=k*F0,s=0.2+0.22k). ANIM animation and BRIGHT are
// presentation only; ANIM's 4*initial-speed retreat is kept through sh_dist(-8) below.
xformdef NOTE_STEP(hold: int, turn_r: angle, final_speed: fx) {
    step_speed(0fx, 60);
    wait(60);
    wait(hold);
    turn(turn_r);
    set_speed(final_speed);
}

// BossCard1_at: 16 etOn calls in one frame, each I0 bullets on one ring; %RANDRAD sampled once per call.
sub volley(i0: int, i1: int, f0: fx) {
    var base: angle = rand(65536) as angle;
    // F0 is radians; target turn is BAM. One truncating conversion per volley, then k*step.
    var f0_bam: int = (f0*10430.378fx) as int;
    var shape: int = TH14_NOTE_BLUE;   // etSprite type 39+$I1: 39 blue, 40 yellow
    if i1 != 0 { shape = TH14_NOTE_YELLOW; }
    for k in 0..16 {
        var turn_r: angle = (f0_bam*k) as angle;
        var final_speed: fx = 0.2fx+(k as fx)*0.22fx;
        sh_reset(0);
        sh_sprite(0, shape, 0);
        sh_ring(0, 1);
        sh_aim(0, 0);
        sh_count(0, i0, 1);
        sh_angle(0, base, 0deg);
        sh_speed(0, 2fx, 0fx);
        sh_offset(0, 0fx, -12fx);   // etOffset(0,0,-12)
        sh_dist(0, -8fx);           // ANIM a=1 spawn retreat 4*initial speed = 8px inward
        sh_xform(0, NOTE_STEP(2*k, turn_r, final_speed));
        sh_fire(0);
    }
}

// moveRand(60,4,1.0) recipe (transcribe/th16/movement.md) adapted to moveLimit(0,128,280,64):
// position clamp x[-140,140] y[96,160]; direction inner zone x+-70, y112..144.
// int slot0 = next-step count; fx slots0/1 = logical unit vector. No source read depends on these slots.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub src_card_wait(frames: int, until: int) {
    for i in 0..frames {
        if $frame >= until { return; }
        wait(1);
        card_arm_next_step();
    }
}
sub src_wait(n: int, until: int) {
    var left: int = until-$frame;
    if left <= 0 { return; }
    if n > left { n = left; }
    if n > 0 { wait(n); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var until: int = $frame+SOURCE_LIMIT;
    var rank: int = global(GVAR_RANK);
    var i0: int = 11;
    if rank == 1 { i0 = 28; }
    if rank == 2 { i0 = 34; }
    if rank == 3 { i0 = 36; }
    var d: int = 60;
    if rank == 0 { d = 120; }
    if rank == 1 { d = 80; }
    // Source t0: t60 completes movePosTime and waits 90; t150 writes diffI(I0) and F0, t210 first volley.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(150);
    var f0: fx = 0.18326fx;
    var i1: int = 1;
    wait(60);
    loop {
        if $frame >= until { break; }
        volley(i0, i1, f0);
        src_wait(d, until);
        if $frame >= until { break; }
        card_move_rand();
        src_card_wait(60, until);
        f0 = 0fx-f0;
        i1 = 1-i1;
        src_wait(60, until);
    }
    // Source t2400 -> Boss2 timeout branch: etClear(640), no next attack.
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48): ordinary circle uses half the width
    set_hurtbox(24fx);  // source setHurtbox(48,48)
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_main);
    loop { wait(600); }
}
